6	const CLIENT_ID = process.env.VITE_SPOTIFY_CLIENT_ID;
7	const CLIENT_SECRET = process.env.SPOTIFY_CLIENT_SECRET;
8	const REDIRECT_URI = "http://127.0.0.1:3000/callback";
9	const FRONTEND_URL = "http://localhost:5173";
10	
11	if (!CLIENT_ID || !CLIENT_SECRET) {
12	  console.error(
13	    "Missing VITE_SPOTIFY_CLIENT_ID or SPOTIFY_CLIENT_SECRET in .env",
14	  );
15	  process.exit(1);
16	}
17	
18	app.get("/callback", async (req, res) => {
19	  const { code, error } = req.query;
20	
21	  if (error || !code) {
22	    return res.redirect(`${FRONTEND_URL}?error=access_denied`);
23	  }
24	
25	  const credentials = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString(
26	    "base64",
27	  );
28	
29	  let tokenResponse;
30	  try {
31	    tokenResponse = await fetch("https://accounts.spotify.com/api/token", {
32	      method: "POST",
33	      headers: {
34	        Authorization: `Basic ${credentials}`,
35	        "Content-Type": "application/x-www-form-urlencoded",
36	      },
37	      body: new URLSearchParams({
38	        grant_type: "authorization_code",
39	        code,
40	        redirect_uri: REDIRECT_URI,
41	      }),
42	    });
43	  } catch (err) {
44	    console.error("Token exchange network error:", err);
45	    return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
46	  }
47	
48	  if (!tokenResponse.ok) {
49	    console.error(
50	      "Token exchange failed:",
51	      tokenResponse.status,
52	      await tokenResponse.text(),
53	    );
54	    return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
55	  }
56	
57	  try {
58	    const { access_token } = await tokenResponse.json();
59	    if (!access_token) {
60	      return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
61	    }
62	    res.redirect(`${FRONTEND_URL}?token=${encodeURIComponent(access_token)}`);
63	  } catch (err) {
64	    console.error("Failed to parse token response:", err);
65	    res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
66	  }
67	});
68	
69	app.listen(3000, "127.0.0.1", () => {
