1	import { useEffect, useRef, useState } from "react";
2	import { lookupArtistLocation } from "../geo.js";
3	import { fetchCurrentlyPlaying } from "../spotify.js";
4	import LeafletMap from "./LeafletMap.jsx";
5	
6	const POLL_MS = 3_000;
7	const PACIFIC_FALLBACK = { lat: 0, lng: -160, placeName: "Unknown location" };
8	
9	export default function MapView({ token, onSessionExpired }) {
10	  const [track, setTrack] = useState(null);
11	  const [location, setLocation] = useState(null);
12	  const [status, setStatus] = useState("loading");
13	  const lastArtistRef = useRef(null);
14	
15	  useEffect(() => {
16	    let cancelled = false;
17	
18	    async function poll() {
19	      try {
20	        const current = await fetchCurrentlyPlaying(token);
21	        if (cancelled) return;
22	
23	        if (!current) {
24	          setStatus("idle");
25	          return;
26	        }
27	
28	        // update track immediately; location catches up asynchronously
29	        setTrack(current);
30	        setStatus("playing");
31	
32	        if (current.artistName !== lastArtistRef.current) {
33	          lastArtistRef.current = current.artistName;
34	          const loc = await lookupArtistLocation(current.artistName);
35	          if (!cancelled) setLocation(loc ?? PACIFIC_FALLBACK);
36	        }
37	      } catch (err) {
38	        if (cancelled) return;
39	        if (err.message === "TOKEN_EXPIRED") {
40	          onSessionExpired();
41	          return;
42	        }
43	        if (err.message.startsWith("RATE_LIMITED:")) {
44	          const seconds = parseInt(err.message.split(":")[1], 10);
45	          // safe to schedule even near unmount: poll() checks cancelled at the top
46	          setTimeout(poll, seconds * 1000);
47	          return;
48	        }
49	        console.error("Poll error:", err);
50	        setStatus("error");
51	      }
52	    }
53	
54	    poll();
55	    const id = setInterval(poll, POLL_MS);
56	    return () => {
57	      cancelled = true;
58	      clearInterval(id);
59	    };
60	  }, [token, onSessionExpired]);
61	
62	  if (status === "idle") {
63	    return (
64	      <div
65	        style={{
66	          display: "flex",
67	          alignItems: "center",
68	          justifyContent: "center",
69	          height: "100vh",
70	          fontFamily: "sans-serif",
71	        }}
72	      >
73	        <p>Play something on Spotify</p>
74	      </div>
75	    );
76	  }
77	
78	  if (status === "error") {
79	    return (
80	      <div
81	        style={{
82	          display: "flex",
83	          alignItems: "center",
84	          justifyContent: "center",
85	          height: "100vh",
86	          fontFamily: "sans-serif",
87	        }}
88	      >
89	        <p>Something went wrong. Check the console.</p>
90	      </div>
91	    );
92	  }
93	
94	  // renders for 'loading' (initial) and 'playing' — LeafletMap handles null track/location
95	  return <LeafletMap track={track} location={location} />;
96	}
